export function currentMonth(today = new Date()): number {
  const s = new Date(phd.startDate);
  const m = (today.getFullYear() - s.getFullYear()) * 12 + (today.getMonth() - s.getMonth()) + 1;
  return Math.min(Math.max(m, 1), phd.durationMonths);
}
